body {
  margin: 0;
  background: #e2e8f0;
}
.wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  width: 100%;
  padding: 20px;
  box-sizing: border-box;
}
.bento-grid {
  width: 100%;
  max-width: 500px;
}
.bento-card {
  background: #7cb5ff;
  padding: 40px 20px;
  border-radius: 20px;
  box-shadow: 0 10px 15px -3px rgba(0,0,0,0.05);
  text-align: center;
  font-weight: 700;
  font-size: 18px;
  color: #334155;
  transition: transform 0.2s;
}
.bento-card:hover {
  transform: translateY(-5px);
}

